//! Break probability by forge grade (MOBILE 3.17.0).
//!
//! Source: `Economy.txt` `config.breakCurve` — 300 entries, one per grade
//! 0..=299, embedded verbatim in `crate::data::BREAK_CURVE` (generated by
//! `tools/gen_data.py`; the parity test in `tests/economy_parity.rs`
//! checks every entry against the extracted mobile file).
//!
//! Shape of the curve: 0% at grade 0, climbing to a 71% plateau at
//! grades 30–99, then 81% at 100–199 and 89% at 200–299. The mobile
//! curve is slightly easier than the PC original's (72/82/90).
//!
//! Break reductions from relics are MULTIPLICATIVE, not subtractive:
//! 30% break with a 20% reduction is 24%, not 10%.

use crate::config::MAX_FORGE_GRADE;
use crate::data::BREAK_CURVE;

/// Base break probability for a sword at `grade`.
///
/// Grades above [`MAX_FORGE_GRADE`] are clamped to the last entry
/// (0.89); swords can never exceed grade 999 in normal play, and the
/// table only covers grades 0..=299, so this is a defensive guard.
pub fn break_chance(grade: u32) -> f64 {
    let idx = (grade.min(299)) as usize;
    let _ = MAX_FORGE_GRADE;
    BREAK_CURVE[idx]
}

/// Apply multiplicative break reductions to a base break chance.
///
/// Each entry of `reductions` is a fraction in `[0, 1]` (e.g. `0.15` for
/// "break chance −15%"). The result is `base * Π(1 − r)`, clamped to
/// `[0, 1]`.
///
/// # Example
/// ```
/// use forgetax_core::break_curve::reduced_break_chance;
/// assert!((reduced_break_chance(0.30, &[0.20]) - 0.24).abs() < 1e-12);
/// ```
pub fn reduced_break_chance(base: f64, reductions: &[f64]) -> f64 {
    let mut chance = base.clamp(0.0, 1.0);
    for r in reductions {
        chance *= 1.0 - r.clamp(0.0, 1.0);
    }
    chance.clamp(0.0, 1.0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn curve_samples_match_mobile_economy() {
        assert_eq!(break_chance(0), 0.0);
        assert!((break_chance(1) - 0.013).abs() < 1e-12);
        assert!((break_chance(2) - 0.053).abs() < 1e-12);
        assert!((break_chance(5) - 0.29).abs() < 1e-12);
        assert!((break_chance(10) - 0.457).abs() < 1e-12);
        assert!((break_chance(20) - 0.62).abs() < 1e-12);
        // Plateau 30–99.
        assert!((break_chance(30) - 0.71).abs() < 1e-12);
        assert!((break_chance(99) - 0.71).abs() < 1e-12);
        // Plateau 100–199.
        assert!((break_chance(100) - 0.81).abs() < 1e-12);
        assert!((break_chance(199) - 0.81).abs() < 1e-12);
        // Plateau 200–299.
        assert!((break_chance(200) - 0.89).abs() < 1e-12);
        assert!((break_chance(299) - 0.89).abs() < 1e-12);
    }

    #[test]
    fn curve_is_monotone_non_decreasing() {
        for g in 1..=299u32 {
            assert!(break_chance(g) >= break_chance(g - 1), "grade {g}");
        }
    }

    #[test]
    fn grade_above_299_clamps_to_last_entry() {
        assert_eq!(break_chance(300), 0.89);
        assert_eq!(break_chance(u32::MAX), 0.89);
    }

    #[test]
    fn reduction_is_multiplicative_not_subtractive() {
        // 30% break with 20% reduction -> 24% (not 10%).
        assert!((reduced_break_chance(0.30, &[0.20]) - 0.24).abs() < 1e-12);
    }

    #[test]
    fn reductions_stack_multiplicatively() {
        // Two 15% reductions: 0.30 * 0.85 * 0.85 = 0.21675.
        let got = reduced_break_chance(0.30, &[0.15, 0.15]);
        assert!((got - 0.21675).abs() < 1e-12);
        // Full immunity clamps at 0, never below.
        assert_eq!(reduced_break_chance(0.5, &[1.0]), 0.0);
        assert_eq!(reduced_break_chance(0.5, &[2.0]), 0.0);
    }
}
